-- =========================================================
-- 🍟 YAGO HUB — TEMA VERMELHO/AMARELO
-- Camada visual: não altera a lógica dos botões.
-- =========================================================

task.spawn(function()
    local Players = game:GetService("Players")
    local player = Players.LocalPlayer
    if not player then return end

    local gui = player:WaitForChild("PlayerGui", 10)
    if not gui then return end

    local RED = Color3.fromRGB(198, 40, 40)
    local RED_DARK = Color3.fromRGB(145, 24, 24)
    local YELLOW = Color3.fromRGB(255, 193, 7)
    local YELLOW_DARK = Color3.fromRGB(230, 160, 0)
    local CREAM = Color3.fromRGB(255, 248, 220)
    local DARK = Color3.fromRGB(32, 27, 39)
    local DARK_2 = Color3.fromRGB(45, 39, 55)

    local function styleMenu(root)
        if not root or not root:IsA("GuiObject") then return end

        -- Fundo principal / cartões
        root.BackgroundColor3 = DARK
        pcall(function() root.BackgroundTransparency = 0.03 end)

        for _, obj in ipairs(root:GetDescendants()) do
            if obj:IsA("TextLabel") then
                local t = string.lower(obj.Text or "")
                if t:find("menu", 1, true) then
                    obj.Text = "🍟 YAGO HUB"
                    obj.TextColor3 = YELLOW
                    obj.Font = Enum.Font.GothamBold
                    obj.TextSize = math.max(obj.TextSize, 18)
                elseif t:find("yago hub", 1, true) then
                    obj.Text = "🍟 YAGO HUB"
                    obj.TextColor3 = YELLOW
                    obj.Font = Enum.Font.GothamBold
                else
                    obj.TextColor3 = CREAM
                end
            elseif obj:IsA("TextButton") then
                local t = string.lower(obj.Text or "")
                if t == "off" then
                    obj.BackgroundColor3 = RED
                    obj.TextColor3 = CREAM
                    obj.Font = Enum.Font.GothamBold
                elseif t == "on" then
                    obj.BackgroundColor3 = YELLOW
                    obj.TextColor3 = Color3.fromRGB(45, 30, 0)
                    obj.Font = Enum.Font.GothamBold
                elseif t:find("whitelist", 1, true) then
                    obj.BackgroundColor3 = YELLOW
                    obj.TextColor3 = Color3.fromRGB(45, 30, 0)
                    obj.Font = Enum.Font.GothamBold
                end
            elseif obj:IsA("Frame") then
                -- Evita pintar elementos totalmente transparentes usados apenas como containers.
                if obj.BackgroundTransparency < 1 then
                    local n = string.lower(obj.Name or "")
                    if n:find("header", 1, true) or n:find("top", 1, true) then
                        obj.BackgroundColor3 = RED
                    else
                        obj.BackgroundColor3 = DARK_2
                    end
                end
            end
        end
    end

    local function findMenu()
        for _, obj in ipairs(gui:GetDescendants()) do
            if obj:IsA("TextLabel") or obj:IsA("TextButton") then
                local t = string.lower(obj.Text or "")
                if t:find("menu", 1, true) or t:find("yago hub", 1, true) then
                    local root = obj
                    -- sobe até encontrar o maior container GuiObject razoável
                    for _ = 1, 8 do
                        local p = root.Parent
                        if not p or not p:IsA("GuiObject") then break end
                        root = p
                    end
                    return root
                end
            end
        end
    end

    local applied = false
    for _ = 1, 80 do
        local menu = findMenu()
        if menu then
            styleMenu(menu)
            applied = true
        end
        if applied then
            -- reaplica algumas vezes porque o script original pode recriar linhas/botões.
            for _ = 1, 10 do
                task.wait(0.5)
                local current = findMenu()
                if current then styleMenu(current) end
            end
            break
        end
        task.wait(0.25)
    end
end)
